CREATE TABLE learning_content_review_events (id VARCHAR(36) PRIMARY KEY, content_type VARCHAR(16) NOT NULL, content_id VARCHAR(36) NOT NULL, content_version INT NOT NULL, event_type VARCHAR(32) NOT NULL, actor_user_id VARCHAR(36) NOT NULL, reason TEXT NOT NULL, permitted_use VARCHAR(32) NOT NULL, created_at VARCHAR(40) NOT NULL, CONSTRAINT chk_learning_content_review_type CHECK (content_type IN ('resource', 'question')), CONSTRAINT chk_learning_content_review_version CHECK (content_version >= 1), CONSTRAINT chk_learning_content_review_event CHECK (event_type IN ('submitted', 'deidentified', 'reviewed', 'published', 'withdrawn', 'rejected')), CONSTRAINT chk_learning_content_review_use CHECK (permitted_use IN ('training', 'public_information')), FOREIGN KEY (actor_user_id) REFERENCES users(id) ON DELETE RESTRICT);
-- statement-break
CREATE INDEX idx_learning_content_review_events_content ON learning_content_review_events(content_type, content_id, content_version, created_at);
